async () => {
const bar=document.getElementById('call-status-bar'); const subs=[...document.querySelectorAll('.call-subtitle')].map(s=>s.innerText.replace(/\n+/g,' ')); const choices=[...document.querySelectorAll('.choice-button')].map(b=>b.innerText.trim()); const hb=document.querySelector('.call-button'); const m=document.querySelector('.messages-container'); return {bar: bar?bar.innerText.replace(/\n+/g,' | '):null, subs, choices, header: hb?hb.innerText.trim():null, thread: m?m.innerText.replace(/\n+/g,' | ').slice(-500):null};

}

